const e={title:"TripReel - App de Carte de Voyage Animée | Créateur de Vidéo des Temps Forts du Voyage",description:"Créez de superbes vidéos des temps forts de voyage et vidéos récapitulatives de voyage avec des cartes animées. App gratuite de carte de voyage animée avec animateur d'itinéraire de voyage et cartographie de route en globe 3D. Transformez vos photos en magnifiques vidéos d'animation de voyage automatiquement. App de carte de voyage animée avec confidentialité d'abord, fonctionne hors ligne.",keywords:"app de carte de voyage animée, app vidéo temps forts voyage, app vidéo récap voyage, app animateur itinéraire voyage, app récap voyages, app carte voyage animée, app animation route voyage, app vidéo carte voyage, app créateur récits voyage, app animation voyage, app créateur vidéo voyage, app animation vol, vidéo voyage automatique, animation trajectoire vol, app animation voyage, animation globe, app photo vers vidéo, temps forts voyage, app voyage gratuite, créateur vidéo hors ligne, app voyage confidentielle, vidéo pellicule"},a={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Comment ça marche",video:"Vidéo",features:"Fonctionnalités",theApp:"L'application"},o={badge:"Transformez vos photos en récits de voyage",title1:"Votre pellicule,",title2:"pleinement exploitée",description:"TripReel est l'app ultime de carte de voyage animée qui crée automatiquement de magnifiques vidéos des temps forts de voyage et vidéos récapitulatives de voyage à partir des localisations de vos photos. Regardez vos périples prendre vie avec notre animateur d'itinéraire de voyage présentant de superbes cartes de parcours animées et des trajectoires de vol à travers un globe 3D, tout en gardant vos données privées et sécurisées.",secure:"100% sécurisé",worksOffline:"Fonctionne hors ligne",globeAlt:"Animation du globe TripReel"},t={title:"Comment ça marche",subtitle:"Trois étapes simples pour créer votre vidéo de voyage parfaite",step1:{title:"Autorisez l'accès aux photos",description:"Accordez à TripReel l'accès à votre photothèque. L'application lit uniquement les métadonnées de localisation, rien d'autre."},step2:{title:"Détection automatique des voyages",description:"TripReel analyse les métadonnées de localisation et identifie intelligemment vos voyages selon les dates et les lieux."},step3:{title:"Générez votre vidéo",description:"Regardez votre voyage se dérouler avec notre animateur d'itinéraire de voyage sur une magnifique animation de globe, créant de superbes vidéos des temps forts de voyage prêtes à partager sur les réseaux sociaux."}},i={title:"Découvrez la magie en action",subtitle:"Voyez comment notre app de carte de voyage animée transforme votre photothèque en superbes vidéos des temps forts de voyage et vidéos récapitulatives de voyage avec des cartes de parcours animées",caption:"Voici à quoi peut ressembler votre vidéo d'animation de voyage finale avec notre app animateur d'itinéraire de voyage"},s={title:"Tout ce dont vous avez besoin",subtitle:"Des fonctionnalités puissantes conçues pour les voyageurs modernes",twoTap:{title:"Vidéos de voyage en deux clics",description:"Créez de superbes vidéos des temps forts de voyage et vidéos récapitulatives de voyage depuis votre photothèque en seulement deux clics avec notre app créateur de vidéo de voyage. Aucun montage nécessaire."},smartTrip:{title:"Détection intelligente des voyages",description:"L'app de récap voyages trouve et regroupe automatiquement vos voyages en analysant les dates et les métadonnées de localisation de vos photos pour créer de parfaites vidéos des temps forts de voyage."},globe:{title:"Magnifique animation de globe",description:"Regardez votre voyage prendre vie avec notre animateur d'itinéraire de voyage présentant un superbe globe 3D montrant vos itinéraires de voyage animés et vos trajectoires de vol à travers le monde dans de magnifiques vidéos de voyage en carte."},privacy:{title:"Confidentialité d'abord",description:"L'app de carte de voyage animée traite tout sur votre appareil. Vos photos ne quittent jamais votre téléphone. Créez des vidéos d'animation de voyage complètement hors ligne en mode avion."},customStyles:{title:"Styles personnalisés",description:"Choisissez parmi plusieurs styles de globe et personnalisations pour vos vidéos d'animation de voyage pour correspondre à votre esthétique et rendre chaque vidéo de carte de voyage animée unique."},manualControl:{title:"Contrôle manuel",description:"L'app animateur d'itinéraire de voyage vous permet d'ajouter manuellement de nouveaux voyages et de personnaliser votre animation de route de voyage si les services de localisation n'étaient pas activés sur votre appareil."}},r={title:"Idées de vidéos créatives",subtitle:"Inspirez-vous de ce que vous pouvez créer avec TripReel, votre app créateur de récits de voyage. Des escapades de week-end rapides aux aventures d'un an, créez de superbes vidéos des temps forts de voyage et vidéos récapitulatives de voyage pour chaque périple.",description:"Que vous créiez une animation de carte de voyage, documentiez un itinéraire de vol avec notre app animateur d'itinéraire de voyage, ou réalisiez une vidéo d'app de récap voyages de fin d'année, TripReel facilite la transformation de vos souvenirs en vidéos d'animation de voyage partageables.",ideas:{yearRecap:{title:"Récap voyages 2025",description:"Créez automatiquement votre récapitulatif annuel de voyages 2025 avec notre app vidéo des temps forts de voyage"},europeRoadTrip:{title:"Road trip européen",description:"Présentez votre aventure européenne avec notre app de carte de voyage animée et des cartes de parcours animées"},southeastAsia:{title:"Voyage en Asie du Sud-Est",description:"Visualisez votre parcours de routard à travers plusieurs pays avec notre app animateur d'itinéraire de voyage"},japanRail:{title:"Voyage en train au Japon",description:"Créez des vidéos de voyage en carte de vos itinéraires en train au Japon avec des cartes de voyage animées"},crossCountry:{title:"Traversée des États-Unis",description:"Transformez votre road trip américain en vidéo d'animation de route de voyage épique avec notre app d'animation de voyage"},islandHopping:{title:"Tour des îles",description:"Montrez vos voyages d'île en île avec de superbes animations 3D en utilisant notre app créateur de récits de voyage"},worldTour:{title:"Montage tour du monde",description:"Combinez plusieurs voyages en une seule vidéo de voyage mondiale extraordinaire avec notre app de carte de voyage animée"},travelPlans:{title:"Projets de voyage 2026",description:"Visualisez et planifiez vos aventures de voyage passionnantes pour 2026 avec notre animateur d'itinéraire de voyage"},lifetimeTravel:{title:"Histoire de voyage d'une vie",description:"Créez une vidéo récap de voyage présentant tous vos voyages de toute une vie avec notre app de récap voyages"},regionalExplorer:{title:"Explorateur régional",description:"Cartographiez vos aventures à travers États, provinces et régions avec notre app de carte de voyage animée"},festivalCircuit:{title:"Circuit des festivals",description:"Tracez votre parcours de festivals de musique et d'événements avec des vidéos de route de voyage animées"},bikeRoutes:{title:"Mes escapades urbaines",description:"Présentez toutes vos escapades citadines avec de magnifiques vidéos de voyage en carte"}}},n={title:"L'application",subtitle:"Disponible maintenant sur l'App Store",alt1:"App de Carte de Voyage Animée - Créez des vidéos des temps forts de voyage automatiquement en quelques secondes",alt2:"Animateur d'Itinéraire de Voyage - Utilise les métadonnées de localisation de vos photos pour des vidéos récapitulatives de voyage",alt3:"Détection des Voyages - Regroupe automatiquement vos voyages pour des vidéos de carte de voyage animées",alt4:"Magnifiques Vidéos de Globe - Animation de globe de votre voyage avec notre app d'animation de voyage",alt5:"Styles Personnalisés - Personnalisez vos vidéos d'animation de route de voyage avec plusieurs styles de globe"},d={comingSoon:"Bientôt disponible",androidTitle:"Application Android bientôt disponible !",androidMessage:'La version Android n\'est pas encore disponible mais le sera bientôt. Envoyez-moi un message à <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> et je vous tiendrai informé dès qu\'elle sera prête !',gotIt:"Compris !"},u={title:"Questions fréquentes",subtitle:"Tout ce que vous devez savoir sur TripReel",q1:{question:"Puis-je utiliser cette app de carte de voyage animée entièrement hors ligne en mode avion ?",answer:"Oui ! Pour les utilisateurs premium, l'app vidéo des temps forts de voyage peut être utilisée complètement hors ligne en mode avion sans aucune limitation. Pour les utilisateurs non-premium, certaines fonctionnalités sont financées par la publicité et peuvent nécessiter d'activer temporairement Internet, mais les utilisateurs premium peuvent créer des vidéos récapitulatives de voyage entièrement hors ligne sans publicités."},q2:{question:"Comment puis-je retirer le filigrane de mes vidéos d'animation de voyage ?",answer:"Beaucoup de personnes demandent quelle app créateur de vidéo de voyage a été utilisée pour créer ces vidéos de carte de voyage animées. Après avoir passé à premium, vous avez l'option d'ajouter une version plus petite du filigrane (avec juste le nom de l'application) ou de le retirer complètement de vos vidéos des temps forts de voyage si vous le souhaitez."},q3:{question:"Mes données photo sont-elles sûres et privées dans cette app animateur d'itinéraire de voyage ?",answer:"Absolument ! L'app de carte de voyage animée lit uniquement les métadonnées de localisation de vos photos - nous n'accédons jamais, ne stockons jamais ni ne transmettons jamais le contenu réel de vos photos. Tout le traitement des vidéos d'animation de voyage se fait localement sur votre appareil, et aucune donnée ne quitte jamais votre téléphone. Vous pouvez le vérifier en créant des vidéos récapitulatives de voyage en mode avion - ça fonctionne parfaitement hors ligne !"},q4:{question:"Que faire si mes photos n'ont pas de données de localisation pour l'animation de route de voyage ?",answer:"Pas de problème ! Si les services de localisation n'étaient pas activés lorsque vous avez pris vos photos, l'app créateur de récits de voyage vous permet de créer manuellement des voyages et d'ajouter vous-même les localisations. L'animateur d'itinéraire de voyage vous donne un contrôle total pour personnaliser votre chronologie de voyage et créer de magnifiques vidéos de carte de voyage animées même sans données GPS."},q5:{question:"Comment cette app de récap voyages détecte-t-elle mes voyages automatiquement ?",answer:"L'app de carte de voyage animée analyse les métadonnées de localisation et les horodatages de vos photos pour identifier intelligemment quand et où vous avez voyagé. Elle regroupe les localisations et dates proches pour détecter automatiquement vos voyages et créer de superbes vidéos des temps forts de voyage sans aucun travail manuel."},q6:{question:"Puis-je personnaliser l'apparence de mes vidéos des temps forts de voyage ?",answer:"Oui ! Notre app d'animation de voyage vous permet de choisir parmi plusieurs styles de globe et de personnaliser divers aspects de vos vidéos de carte de voyage animées pour correspondre à votre esthétique personnelle. Les utilisateurs premium ont accès à des styles d'animation de parcours supplémentaires, des thèmes de cartes et des options de trajectoires de vol."},q7:{question:"Dois-je créer un compte pour utiliser cette app créateur de vidéo de voyage ?",answer:"Aucun compte requis ! L'app d'animation de voyage fonctionne immédiatement après le téléchargement. Pas d'inscription, pas de connexion et aucune information personnelle nécessaire. Téléchargez simplement l'app de carte de voyage animée et commencez à créer vos vidéos de route de voyage animées tout de suite."},q8:{question:"Pourquoi une localisation manque-t-elle dans ma vidéo de carte de voyage animée ?",answer:"L'app animateur d'itinéraire de voyage ne peut fonctionner qu'avec les données disponibles, donc vous avez besoin d'au moins quelques photos à cet endroit avec des données GPS. Assurez-vous que les services de localisation étaient activés lorsque vous y étiez. Parfois une faible réception GPS peut causer des données de localisation incorrectes. Si votre localisation ne s'affiche toujours pas dans votre vidéo des temps forts de voyage, vous pouvez ajouter manuellement cette localisation depuis Vue d'ensemble des voyages > bouton Modifier. Veuillez utiliser Contact pour signaler le problème."},q9:{question:"Où puis-je partager mes vidéos récapitulatives de voyage et animations de route de voyage ?",answer:"Vous pouvez partager vos vidéos d'animation de voyage sur toutes les plateformes sociales ! Notre app de carte de voyage animée permet différents formats d'image (vertical, panoramique, cinéma, carré) pour vos vidéos de carte de voyage animées pour mieux s'adapter à chaque plateforme - parfait pour Instagram, TikTok, YouTube, Facebook et plus encore."},q10:{question:"Où puis-je signaler un bug ?",answer:"Contactez-moi directement à marian@qod.ee en expliquant brièvement quel est le problème."}},p={title:"Assistance par email",description:"Si vous avez des commentaires ou rencontrez des problèmes, n'hésitez pas à me contacter directement à cette adresse email et je lirai et traiterai personnellement votre demande aussi rapidement que possible. Merci d'utiliser l'application !",close:"Fermer"},l={default:{title:"🍪 Cookies",message:"Nous utilisons des cookies sur le site TripReel pour améliorer votre expérience. Aucune donnée personnelle collectée.",accept:"Accepter",decline:"Refuser",details:"Détails"},theme:{title:"🍪 Cookies",message:"🌙 Pour enregistrer votre préférence de thème, vous devez accepter les cookies essentiels sur le site TripReel. Sans eux, votre choix de thème ne peut pas être sauvegardé.",accept:"Accepter",decline:"Refuser",details:"Détails"}},v={privacy:"Politique de confidentialité de l'app",cookies:"Politique de cookies du site",contact:"Contact",cookiePreferences:"Préférences de cookies",madeWith:"Créé avec",forTravelers:"pour les voyageurs du monde entier",copyright:"© {{year}} TripReel."},c={title:"Prêt à partager votre voyage ?",description:"Téléchargez TripReel aujourd'hui et transformez votre pellicule en magnifiques vidéos des temps forts de voyage avec notre app de carte de voyage animée présentant l'animateur d'itinéraire de voyage et l'animation de route de voyage. Vos aventures méritent d'être célébrées avec de superbes vidéos récapitulatives de voyage.",features:"Téléchargement gratuit • Rapide et pratique • Confidentialité garantie"},m={title:"À propos de TripReel",subtitle:"Créateur professionnel de vidéos des temps forts de voyage et app animateur d'itinéraire de voyage",howItWorks:{title:"Comment fonctionne notre app de récap voyages",description:"L'app d'animation de voyage utilise des algorithmes intelligents pour scanner les données GPS de vos photos et détecter automatiquement vos voyages. L'animateur d'itinéraire de voyage crée ensuite des animations de routes de voyage cinématiques et fluides montrant votre chemin à travers les villes, pays et continents. Que vous créiez une vidéo rapide des temps forts de voyage de week-end ou une vidéo récapitulative de voyage d'un an, l'app de carte de voyage animée le rend sans effort."},customization:{title:"Personnalisation étendue pour vos vidéos d'animation de voyage",description:"L'app créateur de récits de voyage offre des options de personnalisation de niveau professionnel pour rendre vos vidéos de carte de voyage animées vraiment uniques :",features:{videoQuality:"Choisissez entre 30 FPS, 60 FPS ou premium 90 FPS pour des animations de route de voyage fluides comme de la soie dans vos vidéos des temps forts de voyage",bitrate:"Ajustez la qualité vidéo (débit binaire) de normale à élevée pour des vidéos de voyage en carte cristallines sans artefacts visuels",earthStyles:"Sélectionnez parmi plusieurs styles de globe magnifiques incluant Réaliste, Lumières Nocturnes, Carte Diurne et vues Satellite pour vos vidéos de carte de voyage animées",borders:"Activez les frontières des pays sur votre animateur d'itinéraire de voyage avec des couleurs et une épaisseur personnalisables pour une visualisation géographique améliorée",aspectRatios:"Créez des vidéos d'animation de voyage aux formats Vertical (9:16), Panoramique (16:9), Cinéma (2.35:1) ou Carré (1:1) parfaits pour Instagram, TikTok, YouTube et autres plateformes sociales",tripSpeed:"Contrôlez la vitesse de l'animateur d'itinéraire de voyage entre les localisations (jusqu'à 3500 km/s) pour créer des vidéos récapitulatives de voyage dynamiques ou relaxées",pauseDuration:"Ajustez la durée de pause à chaque localisation (0.5-5 secondes) pour mettre en évidence les destinations importantes dans vos vidéos des temps forts de voyage",locationLabels:"Affichez les étiquettes de Ville, Région et/ou Pays sur vos vidéos de carte de voyage animées pour fournir le contexte de votre voyage",pathDisplay:"Activez si vous souhaitez afficher tous les chemins de voyages passés ou seulement le voyage actuel dans votre animation de route de voyage"}}},g={meta:e,header:a,hero:o,howItWorks:t,videoSection:i,features:s,videoIdeas:r,screenshots:n,appStore:d,faq:u,contact:p,cookieBanner:l,footer:v,cta:c,about:m};export{m as about,d as appStore,p as contact,l as cookieBanner,c as cta,g as default,u as faq,s as features,v as footer,a as header,o as hero,t as howItWorks,e as meta,n as screenshots,r as videoIdeas,i as videoSection};
